{
  "ok": true,
  "tool": "list_operations",
  "operations": [
    {
      "op": "add_viewport",
      "category": "layout",
      "description": "Add a viewport to a paper-space layout (pass layout=<name>) that shows model space at a fixed scale. center/width/height are on the paper in mm; scale is paper mm per model unit (0.5 = 1:2, 2 = 2:1). view_center defaults to the centre of everything in model space; width/height default to the model extents at that scale plus a 5% margin.",
      "params": {
        "type": "object",
        "properties": {
          "center": {
            "type": "array",
            "items": {
              "type": [
                "number",
                "string"
              ]
            },
            "minItems": 2,
            "maxItems": 2,
            "description": "Viewport centre on the paper (mm) [x, y] (drawing units, or string with unit e.g. '8mm')"
          },
          "scale": {
            "type": "number",
            "description": "Paper mm per model unit, e.g. 0.5 for 1:2",
            "exclusiveMinimum": 0
          },
          "width": {
            "type": "number",
            "description": "Viewport width on the paper (mm)",
            "exclusiveMinimum": 0
          },
          "height": {
            "type": "number",
            "description": "Viewport height on the paper (mm)",
            "exclusiveMinimum": 0
          },
          "view_center": {
            "type": "array",
            "items": {
              "type": [
                "number",
                "string"
              ]
            },
            "minItems": 2,
            "maxItems": 2,
            "description": "Model-space point shown at the viewport centre [x, y] (drawing units, or string with unit e.g. '8mm')"
          },
          "layer": {
            "type": "string",
            "description": "Layer name (created on the fly if missing)"
          },
          "color": {
            "type": "integer",
            "description": "ACI color (256 = BYLAYER)",
            "minimum": 0,
            "maximum": 257
          },
          "linetype": {
            "type": "string",
            "description": "Linetype name, e.g. CONTINUOUS, CENTER, DASHED"
          },
          "lineweight": {
            "type": "integer",
            "description": "Lineweight in 1/100 mm (e.g. 50 = 0.50 mm), -1 = BYLAYER"
          },
          "tag": {
            "type": "string",
            "description": "Semantic tag for later reference as 'tag:<name>'"
          },
          "if_tag_exists": {
            "type": "string",
            "enum": [
              "error",
              "skip",
              "replace"
            ],
            "description": "Behaviour when an entity with this tag already exists (use 'skip' for idempotent replays)",
            "default": "error"
          },
          "layout": {
            "type": "string",
            "description": "Layout to work in: 'Model' (default) or a paper-space layout name from read_drawing. New entities go there and filter selectors search it; edits that derive entities from an existing one (copy, offset, trim, fillet) keep them in that entity's layout"
          }
        },
        "required": [
          "center",
          "scale"
        ],
        "additionalProperties": false
      }
    },
    {
      "op": "create_layout",
      "category": "layout",
      "description": "Create a paper-space layout (a printed sheet) with its paper size. Draw the frame and title block into it with the usual ops and layout=<name>, then show the model with add_viewport.",
      "params": {
        "type": "object",
        "properties": {
          "name": {
            "type": "string",
            "description": ""
          },
          "paper": {
            "type": "string",
            "enum": [
              "A0",
              "A1",
              "A2",
              "A3",
              "A4",
              "custom"
            ],
            "description": "",
            "default": "A3"
          },
          "orientation": {
            "type": "string",
            "enum": [
              "landscape",
              "portrait"
            ],
            "description": "",
            "default": "landscape"
          },
          "width": {
            "type": "number",
            "description": "Paper width in mm (paper='custom')",
            "exclusiveMinimum": 0
          },
          "height": {
            "type": "number",
            "description": "Paper height in mm (paper='custom')",
            "exclusiveMinimum": 0
          },
          "if_exists": {
            "type": "string",
            "enum": [
              "error",
              "skip"
            ],
            "description": "",
            "default": "error"
          },
          "layout": {
            "type": "string",
            "description": "Layout to work in: 'Model' (default) or a paper-space layout name from read_drawing. New entities go there and filter selectors search it; edits that derive entities from an existing one (copy, offset, trim, fillet) keep them in that entity's layout"
          }
        },
        "required": [
          "name"
        ],
        "additionalProperties": false
      }
    }
  ],
  "count": 2,
  "constraint_types": {
    "check": [
      "angle",
      "coincident",
      "concentric",
      "diameter",
      "distance",
      "equal",
      "fixed",
      "horizontal",
      "length",
      "parallel",
      "perpendicular",
      "radius",
      "symmetric",
      "tangent",
      "vertical"
    ],
    "enforce": [
      "coincident",
      "concentric",
      "diameter",
      "distance",
      "equal",
      "fixed",
      "horizontal",
      "length",
      "parallel",
      "perpendicular",
      "radius",
      "vertical"
    ]
  },
  "metrics": {
    "duration_ms": 0.73,
    "input_bytes": 16,
    "output_bytes": 3928
  }
}

